        { title:'Tree-Climbing Lions', text:'Lake Manyara\u2019s famous acacia-climbing lions and rich birdlife along the lake shore.' },
        { title:'The Ngorongoro Crater', text:'A five-hour descent into the world\u2019s largest intact volcanic caldera, home to the Big Five.' },
        { title:'Two Nights in the Serengeti', text:'An immersive big-cat experience across the Central Serengeti\u2019s Seronera Valley.' },
        { title:'Tarangire\u2019s Giants', text:'A final game drive among some of the largest elephant herds in Africa.' }
